package br.com.catalogo;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;import java.util.concurrent.atomic.*;import javax.swing.*;import java.util.function.BooleanSupplier;
@EnabledIfSystemProperty(named="catalogo.guiTest",matches="true")
class PhysicalBookFormTest {
 @TempDir Path root;Biblioteca library;PhysicalBookForm form;AtomicInteger saved=new AtomicInteger();
 interface Action {void run()throws Exception;}
 void edt(Action action)throws Exception{AtomicReference<Throwable> failure=new AtomicReference<>();SwingUtilities.invokeAndWait(()->{try{action.run();}catch(Throwable e){failure.set(e);}});if(failure.get()!=null)throw new AssertionError(failure.get());}
 void await(BooleanSupplier condition)throws Exception{long end=System.currentTimeMillis()+10000;while(System.currentTimeMillis()<end){boolean[] pass={false};edt(()->pass[0]=condition.getAsBoolean());if(pass[0])return;Thread.sleep(30);}fail("Tempo excedido");}
 @BeforeEach void setup()throws Exception{library=new Biblioteca(root.resolve("Livros"));}
 @AfterEach void close()throws Exception{edt(()->{if(form!=null)form.dispose();});}
 void open(PhysicalBookForm.Lookup lookup)throws Exception{edt(()->{UiTheme.install();form=new PhysicalBookForm(null,library,saved::incrementAndGet,lookup);form.setModal(false);form.setVisible(true);});await(()->form.barcode.isFocusOwner());}
 @Test void saveKeepsCurrentBookAndRepeatedSaveUpdatesInsteadOfDuplicating()throws Exception{
  open(code->{var d=new PhysicalBooks.Draft();d.title="Kotlin Essentials";d.barcode=code;d.isbn=code;d.author="Autora";return d;});edt(()->{assertEquals("Salvar alterações",form.register.getText());form.barcode.setText("9780132350884");form.barcode.postActionEvent();});await(()->!form.busy&&form.title.getText().equals("Kotlin Essentials"));assertTrue(library.books().isEmpty());edt(()->form.register.doClick());await(()->saved.get()==1&&!form.busy);String id=library.books().get(0).id;edt(()->{assertEquals("Kotlin Essentials",form.title.getText());form.title.setText("Título revisado");form.register.doClick();});await(()->saved.get()==2&&!form.busy);assertEquals(1,library.books().size());assertEquals(id,library.books().get(0).id);assertEquals("Título revisado",library.books().get(0).title);
 }
 @Test void scannerWithoutEnterOnlyPopulatesUntilSave()throws Exception{
  open(code->{var d=new PhysicalBooks.Draft();d.title="Kotlin Essentials";d.barcode=code;d.isbn=code;return d;});edt(()->form.barcode.setText("9780132350884"));await(()->!form.busy&&form.title.getText().equals("Kotlin Essentials"));assertEquals(0,saved.get());assertTrue(library.books().isEmpty());
 }
 @Test void newBookDiscardsUnsavedDraftAndResetsEveryField()throws Exception{
  open(code->new PhysicalBooks.Draft());edt(()->{form.title.setText("Não salvar");form.author.setText("Autora");form.notes.setText("Nota");form.favorite.setSelected(true);form.page.setValue(8);form.selectCategory("livros_fisicos/Minha categoria");form.newBook.doClick();assertEquals("",form.title.getText());assertEquals("",form.author.getText());assertEquals("",form.notes.getText());assertEquals(1,form.page.getValue());assertFalse(form.favorite.isSelected());assertNull(form.cover.getIcon());assertTrue(form.barcode.isEnabled());});assertTrue(library.books().isEmpty());assertEquals(0,saved.get());
 }
 @Test void newBookCancelsLookupAndDoesNotRepopulateFromOldResult()throws Exception{
  var started=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);try{open(code->{started.countDown();try{release.await();}catch(InterruptedException ignored){}var d=new PhysicalBooks.Draft();d.title="Resultado antigo";return d;});edt(()->{form.barcode.setText("9780132350884");form.barcode.postActionEvent();});assertTrue(started.await(5,java.util.concurrent.TimeUnit.SECONDS));edt(()->{assertTrue(form.newBook.isEnabled());form.newBook.doClick();});release.countDown();Thread.sleep(150);edt(()->{assertEquals("",form.title.getText());assertFalse(form.busy);});assertTrue(library.books().isEmpty());}finally{release.countDown();}
 }
 @Test void lookupOnlyPopulatesUntilRegisterClicked()throws Exception{
  open(code->{var d=new PhysicalBooks.Draft();d.title="Revisar antes de salvar";d.isbn=code;return d;});edt(()->{form.barcode.setText("9780132350884");form.barcode.postActionEvent();});await(()->!form.busy&&form.title.getText().equals("Revisar antes de salvar"));assertTrue(library.books().isEmpty());edt(()->form.register.doClick());await(()->saved.get()==1&&!form.busy);assertEquals(1,library.books().size());
 }
 @Test void lookupDisplaysAndPersistsCoverWithManualOptionsHidden()throws Exception{
  open(code->{var d=new PhysicalBooks.Draft();d.title="Livro com capa";d.isbn=code;d.cover=CoverQueueTest.image();return d;});edt(()->{assertFalse(form.manualCoverActions.isVisible());form.barcode.setText("9780132350884");form.barcode.postActionEvent();});await(()->!form.busy&&form.cover.getIcon()!=null);assertTrue(library.books().isEmpty());edt(()->{assertFalse(form.manualCoverActions.isVisible());assertTrue(form.replaceCover.isVisible());form.replaceCover.doClick();assertTrue(form.manualCoverActions.isVisible());form.register.doClick();});await(()->saved.get()==1&&!form.busy);assertNotNull(BookPreview.stored(library,library.books().get(0).id).image());
 }
 @Test void missingCoverOffersManualFallbackOnlyAfterLookup()throws Exception{
  open(code->{var d=new PhysicalBooks.Draft();d.title="Sem capa nas fontes";d.isbn=code;return d;});edt(()->{assertFalse(form.manualCoverActions.isVisible());form.barcode.setText("9780132350884");form.barcode.postActionEvent();});await(()->!form.busy&&form.title.getText().equals("Sem capa nas fontes"));edt(()->{assertTrue(form.manualCoverActions.isVisible());assertTrue(form.message.getText().contains("último recurso"));});assertTrue(library.books().isEmpty());
 }
 @Test void progressRemainsVisibleUntilCoverSearchFinishes()throws Exception{
  var waiting=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);try{
   open(new PhysicalBookForm.Lookup(){public PhysicalBooks.Draft find(String code){return new PhysicalBooks.Draft();}public PhysicalBooks.Draft find(String code,java.util.function.Consumer<BookLookup.Progress> progress)throws Exception{progress.accept(new BookLookup.Progress(85,"Pesquisando capa em páginas de livrarias…"));waiting.countDown();release.await();var d=new PhysicalBooks.Draft();d.title="Capa encontrada";d.cover=CoverQueueTest.image();return d;}});edt(()->{form.barcode.setText("9788534531238");form.barcode.postActionEvent();});assertTrue(waiting.await(5,java.util.concurrent.TimeUnit.SECONDS));await(()->form.lookupProgress.getString().contains("livrarias"));edt(()->{assertTrue(form.busy);assertTrue(form.lookupProgress.isVisible());assertTrue(form.lookupProgress.isIndeterminate());assertFalse(form.register.isEnabled());});release.countDown();await(()->!form.busy&&form.cover.getIcon()!=null);edt(()->{assertFalse(form.lookupProgress.isIndeterminate());assertEquals(100,form.lookupProgress.getValue());});
  }finally{release.countDown();}
 }
 @Test void lookupSuggestsCategoryAndCustomChoiceDoesNotLeakToNextBook()throws Exception{
  open(code->{var d=new PhysicalBooks.Draft();d.title="Kotlin Essentials";d.isbn=code;return d;});edt(()->{form.barcode.setText("9780132350884");form.barcode.postActionEvent();});await(()->!form.busy&&form.title.getText().equals("Kotlin Essentials"));edt(()->{assertEquals("livros_fisicos/programacao/kotlin",form.categoryButton.getText());form.selectCategory("livros_fisicos/Pessoal/Referência");form.register.doClick();});await(()->saved.get()==1&&!form.busy);assertEquals("livros_fisicos/Pessoal/Referência",library.books().get(0).section);edt(()->{form.newBook.doClick();form.title.setText("Rust Essentials");form.register.doClick();});await(()->saved.get()==2&&!form.busy);assertTrue(library.books().stream().anyMatch(b->b.title.equals("Rust Essentials")&&b.section.equals("livros_fisicos/programacao/rust")));
 }
 @Test void editFormLoadsAndSavesPhysicalBook()throws Exception{
  var d=new PhysicalBooks.Draft();d.title="Meu livro";d.author="Autora";PhysicalBooks.save(library,d);open(code->new PhysicalBooks.Draft());edt(()->{form.edit(library.books().get(0));assertEquals("Meu livro",form.title.getText());assertEquals("Autora",form.author.getText());assertEquals("Salvar alterações",form.register.getText());form.title.setText("Atualizado");form.register.doClick();});await(()->saved.get()==1);assertEquals("Atualizado",library.books().get(0).title);
 }
 @Test void newBookDiscardsEditsAndNextSaveCreatesSeparateRecord()throws Exception{
  var d=new PhysicalBooks.Draft();d.title="Livro original";PhysicalBooks.save(library,d);String original=library.books().get(0).id;open(code->new PhysicalBooks.Draft());edt(()->{form.edit(library.books().get(0));form.title.setText("Edição descartada");form.newBook.doClick();assertEquals("",form.title.getText());form.title.setText("Livro novo");form.register.doClick();});await(()->saved.get()==1&&!form.busy);assertEquals(2,library.books().size());assertEquals("Livro original",library.books().stream().filter(b->b.id.equals(original)).findFirst().orElseThrow().title);assertTrue(library.books().stream().anyMatch(b->b.title.equals("Livro novo")));
 }
 @Test void manualCoverActionRemainsAccessibleInitiallyAfterFailureAndReset()throws Exception{
  open(code->{throw new java.io.IOException("Sem conexão");});edt(()->{assertTrue(form.replaceCover.isVisible());form.replaceCover.doClick();assertTrue(form.chooseCover.isShowing());form.replaceCover.doClick();form.barcode.setText("9780132350884");form.barcode.postActionEvent();});await(()->!form.busy&&form.message.getText().contains("Sem conexão"));edt(()->{assertTrue(form.replaceCover.isVisible());form.newBook.doClick();assertTrue(form.replaceCover.isVisible());form.replaceCover.doClick();assertTrue(form.chooseCover.isShowing());});assertTrue(library.books().isEmpty());
 }
 @Test void savingEditedBookResetsFormAndKeepsConcurrentReadingChanges()throws Exception{
  var d=new PhysicalBooks.Draft();d.title="Original";PhysicalBooks.save(library,d);var baseline=library.books().get(0);open(code->new PhysicalBooks.Draft());edt(()->form.edit(baseline));var other=library.books().get(0);library.saveProgress(other,56);other.notes="Anotação externa";library.save(other);edt(()->{form.title.setText("Título atualizado");form.register.doClick();});await(()->saved.get()==1&&!form.busy);var actual=library.books().get(0);assertEquals("Título atualizado",actual.title);assertEquals("Anotação externa",actual.notes);assertEquals(56,actual.page);assertTrue(actual.reading);edt(()->{assertEquals("",form.title.getText());assertNull(form.editing);});
 }
 @Test void closeButtonCancelsLookupWithoutSaving()throws Exception{
  var started=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);
  try{open(code->{started.countDown();try{release.await();}catch(InterruptedException ignored){}var d=new PhysicalBooks.Draft();d.title="Não salvar";return d;});edt(()->{form.barcode.setText("9780132350884");form.barcode.postActionEvent();});assertTrue(started.await(5,java.util.concurrent.TimeUnit.SECONDS));edt(()->{assertTrue(form.closeButton.isEnabled());form.closeButton.doClick();assertFalse(form.isDisplayable());});}finally{release.countDown();}assertEquals(0,saved.get());assertTrue(library.books().isEmpty());
 }
 @Test void physicalNotesOnlyPersistWhenSaveChangesIsClicked()throws Exception{
  var d=new PhysicalBooks.Draft();d.title="Livro físico";d.notes="Original";PhysicalBooks.save(library,d);CatalogoApp[] app={null};try{edt(()->{app[0]=new CatalogoApp(library,false);app[0].setVisible(true);});await(()->app[0].selected!=null);edt(()->{app[0].notes.setText("Revisada");assertTrue(app[0].saveChanges.isEnabled());assertFalse(app[0].autoSave.isRunning());assertTrue(app[0].save());});assertEquals("Original",library.books().get(0).notes);edt(()->app[0].saveChanges.doClick());assertEquals("Revisada",library.books().get(0).notes);edt(()->{app[0].notes.setText("Descartar ao sair");app[0].dispatchEvent(new java.awt.event.WindowEvent(app[0],java.awt.event.WindowEvent.WINDOW_CLOSING));});assertEquals("Revisada",library.books().get(0).notes);}finally{edt(()->{if(app[0]!=null){app[0].closed=true;app[0].searchDelay.stop();app[0].autoSave.stop();app[0].dispose();}});}
 }
 @Test void physicalActionsFitMinimumWindowAndDigitalCannotBeDeleted()throws Exception{
  var d=new PhysicalBooks.Draft();d.title="Livro físico";PhysicalBooks.save(library,d);OrganizerTest.pdf(library.root.resolve("Kotlin.pdf"),"Kotlin Essentials");new LibraryOrganizer(library).organize((p,m)->{});CatalogoApp[] app={null};try{
   edt(()->{app[0]=new CatalogoApp(library,false);app[0].setSize(1050,700);app[0].setVisible(true);});await(()->app[0].selected!=null);
   edt(()->{var physical=library.books().stream().filter(Biblioteca.Book::physical).findFirst().orElseThrow();app[0].fill(physical);app[0].validate();for(var button:java.util.List.of(app[0].editButton,app[0].deleteButton,app[0].saveChanges)){if(button!=app[0].saveChanges)assertTrue(button.isEnabled());assertTrue(new java.awt.Rectangle(0,0,button.getParent().getWidth(),button.getParent().getHeight()).contains(button.getBounds()),button.getText()+" cortado no painel");var bounds=SwingUtilities.convertRectangle(button.getParent(),button.getBounds(),app[0].getContentPane());assertTrue(((JComponent)app[0].getContentPane()).getVisibleRect().contains(bounds),button.getText()+" fora da janela: "+bounds);}var digital=library.books().stream().filter(b->!b.physical()).findFirst().orElseThrow();app[0].fill(digital);assertTrue(app[0].move.isEnabled());assertTrue(new java.awt.Rectangle(0,0,app[0].move.getParent().getWidth(),app[0].move.getParent().getHeight()).contains(app[0].move.getBounds()),"Alterar categoria deve ficar visível");assertFalse(app[0].deleteButton.isEnabled());app[0].confirmDelete=b->{fail("Não deve excluir digital");return true;};app[0].deleteSelected();});assertEquals(2,library.books().size());
  }finally{edt(()->{if(app[0]!=null){app[0].closed=true;app[0].searchDelay.stop();app[0].autoSave.stop();app[0].dispose();}});}
 }
 @Test void deleteButtonRequiresConfirmationAndRemovesSelectedRegistration()throws Exception{
  var d=new PhysicalBooks.Draft();d.title="Livro para excluir";PhysicalBooks.save(library,d);CatalogoApp[] app={null};try{edt(()->{app[0]=new CatalogoApp(library,false);app[0].setVisible(true);});await(()->app[0].selected!=null);edt(()->{app[0].confirmDelete=b->false;app[0].deleteButton.doClick();});assertEquals(1,library.books().size());edt(()->{app[0].confirmDelete=b->true;app[0].deleteButton.doClick();});await(()->!app[0].busy&&app[0].all.isEmpty());assertTrue(library.books().isEmpty());}finally{edt(()->{if(app[0]!=null){app[0].closed=true;app[0].searchDelay.stop();app[0].autoSave.stop();app[0].dispose();}});}
 }
 @Test void manualRegistrationNeedsNoBarcodeAndLookupFailureKeepsFormEditable()throws Exception{
  open(code->{throw new java.io.IOException("Serviço indisponível");});edt(()->{form.barcode.setText("9780132350884");form.barcode.postActionEvent();});await(()->!form.busy&&form.message.getText().contains("indisponível"));assertTrue(library.books().isEmpty());edt(()->{form.barcode.setText("");form.title.setText("Livro de Java");form.author.setText("Maria");form.register.doClick();});await(()->saved.get()==1&&!form.busy);assertEquals("Maria",library.books().get(0).meta("author"));
 }
 @Test void mainSearchIncludesBothCollectionsAndPhysicalBooksDoNotOpenAsFiles()throws Exception{
  OrganizerTest.pdf(library.root.resolve("Kotlin.pdf"),"Kotlin Essentials");new LibraryOrganizer(library).organize((p,m)->{});var d=new PhysicalBooks.Draft();d.title="Kotlin Essentials";d.summary="Livro de programação";PhysicalBooks.save(library,d);
  CatalogoApp[] app={null};try{
   edt(()->{app[0]=new CatalogoApp(library,false);app[0].setVisible(true);app[0].category=LibraryCategories.PHYSICAL;app[0].search.setText("kotlin");});
   await(()->app[0].appliedSerial==app[0].searchSerial&&!app[0].searchDelay.isRunning());
   edt(()->{assertEquals(2,app[0].visible.size());int physical=-1;for(int i=0;i<app[0].visible.size();i++)if(app[0].visible.get(i).physical())physical=i;assertTrue(physical>=0);app[0].table.setRowSelectionInterval(physical,physical);assertTrue(app[0].selected.physical());assertFalse(app[0].open.isEnabled());assertFalse(app[0].move.isEnabled());});
  }finally{edt(()->{if(app[0]!=null){app[0].closed=true;app[0].resetPreview();app[0].searchDelay.stop();app[0].autoSave.stop();app[0].dispose();}});}
 }

}
